import { createElement, RawHTML, useState } from '@wordpress/element';
import { Button, Modal } from '@wordpress/components';
import { __, sprintf } from '@wordpress/i18n';
import { decodeEntities } from '@wordpress/html-entities';
import { QuestionLivePreview } from '../question-bank/QuestionLivePreview';

/** Direct author preview of the current draft; no course launch or attempt creation. */
export function QuizFormPreview({ quiz, questions, onClose }) {
  const [reset, setReset] = useState(0);
  return (
    <Modal
      title={__('Quiz preview', 'ohmylms')}
      onRequestClose={onClose}
      className="ohmylms-quiz-preview-modal"
      size="large"
    >
      <div className="ohmylms-quiz-preview-form">
        <header className="ohmylms-quiz-preview-introduction">
          <h1>{decodeEntities(quiz?.name || __('Untitled quiz', 'ohmylms'))}</h1>
          <RawHTML>{quiz?.description || ''}</RawHTML>
          <p className="ohmylms-preview-note">
            {__('Preview of your current draft. Responses are not saved or graded.', 'ohmylms')}
          </p>
        </header>
        <div key={reset} className="ohmylms-quiz-preview-questions">
          {questions.map((question, index) => (
            <article
              className="ohmylms-quiz-preview-card"
              key={question.id ?? index}
              aria-label={sprintf(__('Question %d', 'ohmylms'), index + 1)}
            >
              <div className="ohmylms-quiz-preview-card-heading">
                <span>{sprintf(__('Question %d', 'ohmylms'), index + 1)}</span>
                {question.settings?.required && (
                  <span className="ohmylms-quiz-preview-required">
                    {__('Required', 'ohmylms')} *
                  </span>
                )}
              </div>
              <QuestionLivePreview question={question} showNote={false} />
            </article>
          ))}
        </div>
        {!questions.length && <p>{__('Add a question to preview your quiz.', 'ohmylms')}</p>}
        <div className="ohmylms-quiz-preview-actions">
          <Button variant="secondary" onClick={() => setReset((value) => value + 1)}>
            {__('Clear answers', 'ohmylms')}
          </Button>
          <Button variant="primary" onClick={onClose}>
            {__('Back to editor', 'ohmylms')}
          </Button>
        </div>
      </div>
    </Modal>
  );
}
